from itertools import permutations

valid_distributions = []
for a in range(31):
    for b in range(a, 31 - a):
        c = 30 - a - b
        if c < b:
            continue
        if (b - a == 6) or (c - b == 6) or (c - a == 6):
            valid_distributions.append((a, b, c))

def worst_case_payoff(g, partitions):
    worst_overall = float('inf')
    for part in partitions:
        worst_perm = float('inf')
        for perm in set(permutations(part)):
            payoff = sum(gi if gi <= xi else 0 for gi, xi in zip(g, perm))
            if payoff < worst_perm:
                worst_perm = payoff
        if worst_perm < worst_overall:
            worst_overall = worst_perm
    return worst_overall

# Optimization: only need g with 0 <= g1 <= g2 <= g3 <= 30
best_guaranteed = -1
best_g = None
for g1 in range(25):
    for g2 in range(g1, 25):
        for g3 in range(g2, 25):
            val = worst_case_payoff((g1, g2, g3), valid_distributions)
            if val > best_guaranteed:
                best_guaranteed = val
                best_g = (g1, g2, g3)

print("Best guaranteed with 12 partitions:", best_guaranteed, best_g)

valid_dist_min2 = [d for d in valid_distributions if d[0] >= 2]
best_guaranteed2 = -1
best_g2 = None
for g1 in range(25):
    for g2 in range(g1, 25):
        for g3 in range(g2, 25):
            val = worst_case_payoff((g1, g2, g3), valid_dist_min2)
            if val > best_guaranteed2:
                best_guaranteed2 = val
                best_g2 = (g1, g2, g3)

print("Best guaranteed with min >= 2:", best_guaranteed2, best_g2)

